def evolved_fsdp_ag_layout(shards, rank, world_size, num_devices, cores_per_device, xm, torch, num_nodes=1):
    """leading-dimension gathers with the native all-gather lowering (pin_layout=False), column shards transposed around it"""
    outs = []
    for s in shards:
        if s.shape[0] == 2048:
            outs.append(xm.all_gather(s.transpose(0, 1).contiguous(), dim=0, pin_layout=False).transpose(0, 1))
        else:
            outs.append(xm.all_gather(s, dim=0, pin_layout=False))
    return outs

